entries[236335] = { ["name"] = "Teer absorbieren", ["text"] = "Nahkampfreichweite\nSofort\nDer Teertyrann absorbiert einen reanimierten Schlick in der Nähe und heilt sich um 0% seiner maximalen Gesundheit.\nDadurch erhöht sich auch der verursachte Schaden des Tyrannen für bis Abbruch um 507965%." }
entries[236336] = { ["name"] = "Teer härten", ["text"] = "300 Meter Reichweite\nSofort\nDie geothermische Hitze der Teergruben geht zurück und sie beginnen sich zu schließen. Nach 3 Sek. sind die Teergruben vollständig ausgehärtet. Jeder Spielercharakter, der zu diesem Zeitpunkt in einer Grube ist, stirbt." }
