entries[236357] = { ["name"] = "Quell von Elune", ["text"] = "Sofort\nDer Boden des Quells wechselt kontinuierlich mit den Mondphasen. Wer auf der hellen Seite des Mondes steht, erhält alle 3 Sek. Stapel von ' Lunardurchdringung ', wer auf der dunklen Seite des Mondes steht, erhält hingegen alle 3 Sek. Stapel von ' Umbraldurchdringung '. Ein Wechsel von einer Seite des Mondes auf die andere entfernt alle Stapel der Durchdringung und löst ' Astrale Säuberung ' aus." }
entries[236358] = { ["name"] = "Teerschlag", ["text"] = "300 Meter Reichweite\nSofort\nDer Zaubernde schlägt auf das Ziel ein, fügt ihm körperlichen Schaden zu und überzieht es mit Teer. Verringert die Bewegungsgeschwindigkeit sowie das Zauber- und Angriffstempo des Ziels außerdem um 20%.\nWenn das Ziel mit 5 Teerstapeln belegt ist, wird es im Teer eingeschlossen.\n\nIm Teer eingeschlossen\n300 Meter Reichweite\n\nSofort Das Opfer ist im Teer eingeschlossen! Es ist für 8 Sek. handlungsunfähig und erstickt, wodurch es alle 1 Sek. 20% seiner maximalen Gesundheit verliert." }
entries[236359] = { ["name"] = "Teufelsschleim", ["text"] = "Nahkampfreichweite\nSofort\nSpritzt hocherhitzten Teufelsschleim auf Gegner in der Nähe, verursacht Feuerschaden und verringert die Bewegungsgeschwindigkeit 8 Sek. lang um 25%." }
entries[236360] = { ["name"] = "Im Teer eingeschlossen", ["text"] = "300 Meter Reichweite\nSofort\nDas Opfer ist im Teer eingeschlossen! Es ist für 8 Sek. handlungsunfähig und erstickt, wodurch es alle 1 Sek. 20% seiner maximalen Gesundheit verliert." }
entries[236361] = { ["name"] = "Geisterketten", ["text"] = "60 Meter Reichweite\nWirken in 2 sek.\nGeisterketten fliegen auf einen Spielercharakter zu, fügen ihm 20784 Schattenschaden zu und verringern seine Bewegungsgeschwindigkeit 30 Sek. lang um 25%. Die Ketten verhindern, dass der Spielercharakter spirituelle Quelle verwendet." }
entries[236362] = { ["name"] = "Teufelsfäule beschwören" }
entries[236363] = { ["name"] = "Stampfen", ["text"] = "300 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde stampft mehrmals auf den Boden auf, fügt allen Spielercharakteren in der Nähe körperlichen Schaden zu und stößt sie weg." }
entries[236364] = { ["name"] = "Stampfen", ["text"] = "300 Meter Reichweite\nSofort\nDer Zaubernde stampft mehrmals auf den Boden auf, fügt allen Spielercharakteren in der Nähe körperlichen Schaden zu und stößt sie weg." }
