entries[236369] = { ["name"] = "Einschlag", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Zaubernde stößt das Ziel zurück und fügt ihm körperlichen Schaden zu. Wenn das Ziel landet, erleidet es körperlichen Schaden, der geringer ausfällt, je weiter es geflogen ist.\nNach der Landung erleidet das Ziel im Verlauf von 15 Sek. zusätzlich 30% Schaden." }
entries[236370] = { ["name"] = "Dämonischer Aufruhr", ["text"] = "100 Meter Reichweite\nSofort\nSchleudert Teufelsenergie auf zufällige Gegner, die Ziele mit einer Aura belegt. Beim Ablauf der Aura bricht am Zielort ein Teufelsstachel hervor, der Gegnern innerhalb von 5 Metern 14552 Feuerschaden zufügt und sie zurückstößt. Zudem erleiden Gegner innerhalb von 18 Metern 1380 Feuerschaden." }
