entries[236372] = { ["name"] = "Teufelsrachentoxin", ["text"] = "Nahkampfreichweite\nSofort\nBeißt zu und injiziert ein verfluchtes Toxin, das 4 Sek. lang pro Sekunde 8 Schattenschaden verursacht. Wirkt nicht bei Dämonen. Dieser Effekt ist stapelbar." }
