entries[236386] = { ["name"] = "Klingentanz", ["text"] = "Sofort 1.5 min Abklingzeit\nWerdet zu einem unaufhaltsamen Sturm der Zerstörung und fügt allen Zielen innerhalb von 8 Metern im Verlauf von 6 Sek. [ Blutdurst : mit beiden Waffen [7 * (0% + (208.95% der Angriffskraft)%)] körperlichen Schaden / (7 * 0%) körperlichen Schaden] zu.\n\nIhr seid dabei gegen bewegungseinschränkende und Kontrollverlusteffekte immun, könnt defensive Fähigkeiten einsetzen und Angriffe vermeiden." }
entries[236387] = { ["name"] = "Kolossaler Hieb", ["text"] = "Nahkampfreichweite\nSofort 1 sek. Abklingzeit\nZerschlitzt die Rüstung des Gegners, verursacht körperlichen Schaden und erhöht den Schaden, den Ihr dem Ziel zufügt, 6 Sek. lang um 100%." }
