entries[236438] = { ["name"] = "Kriegsbanner", ["text"] = "Stellt zu Euren Füßen ein Kriegsbanner auf, das Eure Verbündeten ermutigt.\n\nErhöht die Bewegungsgeschwindigkeit um 30%. Verringert die Dauer aller Kontrollverlusteffekte, die auf Verbündete gewirkt werden, um 50%. Wirkt auf alle Verbündeten innerhalb von 30 Metern um das Kriegsbanner. Hält 15 Sek. lang an." }
