entries[236440] = { ["name"] = "Stärke der Wildnis", ["text"] = "Sofort\nIhr werdet noch geschickter im Umgang mit Eurer nicht verwandelten Gestalt und Eurer Bärengestalt.\n\nNicht verwandelte Gestalt\nWenn Ihr 'Nachwachsen' auf einen Verbündeten wirkt, ist die kritische Trefferchance der Initialheilung um 30% erhöht. Außerdem wird die Zauberzeit von 'Nachwachsen' für 6 Sek. um 50% verringert.\n\nBärengestalt\nWährend Ihr Euch in Bärengestalt befindet, ist Eure maximale Gesundheit um 15% erhöht und Ihr erzeugt 5 Wut, wenn Ihr angegriffen werdet.\n\nZusätzlich erlernt Ihr:\n\nStärke der Wildnis\nZermalmt das Ziel und fügt ihm 8% seiner maximalen Gesundheit als körperlichen Schaden zu.\n(2s Abklingzeit)" }
entries[236442] = { ["name"] = "Zwielichtsalve", ["text"] = "150 Meter Reichweite\nWirken in 3 sek.\nSchattenpfeile regnen vom Himmel herab und verursachen alle 1.5 Sek. 12818 Schattenschaden." }
